47	function intersects(left: LayoutRect, right: LayoutRect, padding = 22) {
48	  return left.x < right.x + right.width + padding
49	    && left.x + left.width + padding > right.x
50	    && left.y < right.y + right.height + padding
51	    && left.y + left.height + padding > right.y;
52	}
