179	function edgeLabelSize(label: string) {
180	  const units = textUnits(label);
181	  return {
182	    width: Math.max(42, Math.min(168, Math.round(units * 7.1 + 18))),
183	    height: units > 22 ? 34 : 20,
184	  };
185	}
