187	function routeMidpoint(points: Array<{ x: number; y: number }>) {
188	  if (points.length < 2) return undefined;
189	  const segments = points.slice(0, -1).map((start, index) => ({
190	    start,
191	    end: points[index + 1],
192	    length: Math.abs(points[index + 1].x - start.x) + Math.abs(points[index + 1].y - start.y),
193	  }));
194	  const total = segments.reduce((sum, segment) => sum + segment.length, 0);
195	  let remaining = total / 2;
196	  for (const segment of segments) {
197	    if (remaining > segment.length) {
198	      remaining -= segment.length;
199	      continue;
200	    }
201	    const ratio = segment.length === 0 ? 0 : remaining / segment.length;
202	    return {
203	      x: segment.start.x + (segment.end.x - segment.start.x) * ratio,
204	      y: segment.start.y + (segment.end.y - segment.start.y) * ratio,
205	    };
206	  }
207	  return points[Math.floor(points.length / 2)];
208	}
