219	function routeSides(relationship: SemanticRelationship, orientation: LayoutOrientation) {
220	  return {
221	    sourceSide: rotateSide(relationship.layoutHints?.sourcePortSide, "right", orientation),
222	    targetSide: rotateSide(relationship.layoutHints?.targetPortSide, "left", orientation),
223	  };
224	}
