import { MarkerType, type Edge, type Node } from "@xyflow/react";
import { visibleObjectIds, type CanvasViewModel } from "./interaction";
import type { CanvasLayout } from "./layout";
import { indexSemanticGraph, type SemanticFlowStep, type SemanticGraph } from "./semantic-graph";
import type { ObjectNodeData, RegionNodeData, RelationshipEdgeData } from "./types";

export type CanvasObjectNode = Node<ObjectNodeData, "object">;
export type CanvasRegionNode = Node<RegionNodeData, "region">;
export type CanvasNode = CanvasObjectNode | CanvasRegionNode;
export type CanvasRelationshipEdge = Edge<RelationshipEdgeData, "relationship">;

function handleId(side: "left" | "right" | "top" | "bottom", role: "source" | "target") {
  return `${role}-${side}`;
}

function flowTransition(
  steps: SemanticFlowStep[],
  sourceObjectId: string,
  targetObjectId: string,
) {
  const stepById = new Map(steps.map((step) => [step.id, step]));
  for (const step of steps) {
    if (step.objectId !== sourceObjectId) continue;
    const next = step.nextStepIds.map((id) => stepById.get(id)).find((candidate) => candidate?.objectId === targetObjectId);
    if (!next) continue;
    const payload = step.outputs.length > 0 ? step.outputs.join(" + ") : next.inputs.join(" + ");
    return { sequence: step.sequence, payload, detail: `${step.title} → ${next.title}` };
  }
  return null;
}

export function projectSemanticGraph(
  graph: SemanticGraph,
  layout: CanvasLayout,
  view: CanvasViewModel,
): { nodes: CanvasNode[]; edges: CanvasRelationshipEdge[] } {
  const index = indexSemanticGraph(graph);
  const visibleIds = visibleObjectIds(graph, view);
  const activeFlow = view.activeFlowId ? index.flowById.get(view.activeFlowId) : undefined;
  const regionNodes = graph.regions
    .map<CanvasRegionNode | null>((region) => {
      const rect = layout.regionRects[region.id];
      if (!rect) return null;
      return {
        id: region.id,
        type: "region",
        position: { x: rect.x, y: rect.y },
        data: {
          region,
          emphasis: view.regionEmphasis.get(region.id) ?? "normal",
          zoomLevel: view.zoomLevel,
          objectCount: index.objectsByRegionId.get(region.id)?.length ?? 0,
          childRegionCount: index.childRegionsByRegionId.get(region.id)?.length ?? 0,
          depth: rect.depth,
        },
        draggable: false,
        selectable: false,
        focusable: false,
        zIndex: 0,
        style: { width: rect.width, height: rect.height },
      };
    })
    .filter((node): node is CanvasRegionNode => Boolean(node));

  const objectNodes = graph.objects
    .filter((object) => visibleIds.has(object.id))
    .map<CanvasObjectNode | null>((object) => {
      const rect = layout.objectRects[object.id];
      if (!rect) return null;
      return {
        id: object.id,
        type: "object",
        position: { x: rect.x, y: rect.y },
        data: {
          object,
          emphasis: view.objectEmphasis.get(object.id) ?? "normal",
          zoomLevel: view.zoomLevel,
          zoom: view.zoom,
          incomingCount: index.incomingByObjectId.get(object.id)?.length ?? 0,
          outgoingCount: index.outgoingByObjectId.get(object.id)?.length ?? 0,
          flowSteps: (activeFlow?.steps ?? [])
            .filter((step) => step.objectId === object.id)
            .map((step) => ({ sequence: step.sequence, role: step.role, title: step.title })),
        },
        draggable: true,
        selectable: true,
        selected: view.selection?.kind === "object" && view.selection.id === object.id,
        zIndex: view.objectEmphasis.get(object.id) === "primary" ? 30 : 10,
        style: { width: rect.width, height: rect.height },
      };
    })
    .filter((node): node is CanvasObjectNode => Boolean(node));

  const edges = graph.relationships
    .filter((relationship) => visibleIds.has(relationship.sourceObjectId) && visibleIds.has(relationship.targetObjectId))
    .map<CanvasRelationshipEdge>((relationship) => {
    const route = layout.relationshipRoutes[relationship.id];
    const emphasis = view.relationshipEmphasis.get(relationship.id) ?? "normal";
    const transition = activeFlow ? flowTransition(activeFlow.steps, relationship.sourceObjectId, relationship.targetObjectId) : null;
    const active = emphasis === "active";
    const renderedRoute = view.mode === "trace" && active ? undefined : route;
    const markerColor = active
      ? "#e8f4ee"
      : emphasis === "suppressed"
        ? "#243137"
        : emphasis === "muted"
          ? "#4c5d62"
          : relationship.state.severity === "critical"
            ? "#b98580"
            : "#83939a";
    return {
      id: relationship.id,
      source: relationship.sourceObjectId,
      target: relationship.targetObjectId,
      sourceHandle: handleId(route?.sourceSide ?? "right", "source"),
      targetHandle: handleId(route?.targetSide ?? "left", "target"),
      type: "relationship",
      data: {
        relationship,
        route: renderedRoute,
        emphasis,
        zoomLevel: view.zoomLevel,
        activeFlowName: activeFlow?.name,
        flowSequence: transition?.sequence,
        flowPayload: transition?.payload,
      },
      markerEnd: { type: MarkerType.ArrowClosed, width: active ? 18 : 15, height: active ? 18 : 15, color: markerColor },
      selected: view.selection?.kind === "relationship" && view.selection.id === relationship.id,
      selectable: emphasis !== "suppressed",
      focusable: emphasis !== "suppressed",
      zIndex: active ? 24 : emphasis === "related" ? 14 : 1,
    };
    });

  return { nodes: [...regionNodes, ...objectNodes], edges };
}

"use client";

import type { CanvasMode, CanvasSelection } from "./interaction";
import type { InspectorBinding } from "./inspector-binding";
import type { SemanticRelationship } from "./semantic-graph";

const TYPE_COPY: Record<string, string> = {
  service: "Service",
  agent: "Agent",
  storage: "Storage",
  external: "External",
  data: "Data",
  control: "Control",
  event: "Event",
  dependency: "Dependency",
};

function RelationshipList({
  relationships,
  direction,
  onSelect,
}: {
  relationships: SemanticRelationship[];
  direction: "in" | "out";
  onSelect: (selection: CanvasSelection) => void;
}) {
  if (relationships.length === 0) return <p className="inspector-empty">No declared relationships.</p>;
  return (
    <div className="inspector-relation-list">
      {relationships.slice(0, 12).map((relationship) => (
        <button key={relationship.id} onClick={() => onSelect({ kind: "relationship", id: relationship.id })} type="button">
          <span>{direction === "out" ? "→" : "←"}</span>
          <strong>{relationship.label || TYPE_COPY[relationship.relationshipType]}</strong>
          <small>{direction === "out" ? relationship.targetObjectId : relationship.sourceObjectId}</small>
        </button>
      ))}
    </div>
  );
}

export default function Inspector({
  binding,
  mode,
  onClose,
  onFocus,
  onSelect,
}: {
  binding: InspectorBinding | null;
  mode: CanvasMode;
  onClose: () => void;
  onFocus: (objectId: string) => void;
  onSelect: (selection: CanvasSelection) => void;
}) {
  return (
    <aside className={`canvas-inspector ${binding ? "open" : ""}`} aria-hidden={!binding} aria-label="Canvas Inspector">
      {binding && (
        <>
          <header className="inspector-heading">
            <div>
              <small>{TYPE_COPY[binding.typeLabel] ?? binding.typeLabel}</small>
              <strong>{binding.title}</strong>
            </div>
            <button aria-label="Close Inspector" onClick={onClose} type="button">×</button>
          </header>

          <section className="inspector-identity" aria-label="Identity and state">
            <p>{binding.summary}</p>
            <dl>
              <div><dt>State</dt><dd><i className={`severity-${binding.state.severity}`} />{binding.state.label}</dd></div>
              <div><dt>Where</dt><dd>{binding.location}</dd></div>
              <div><dt>Mode</dt><dd>{mode}</dd></div>
            </dl>
            {binding.kind === "object" && (
              <button className="inspector-focus-action" disabled={mode === "focus"} onClick={() => onFocus(binding.object.id)} type="button">
                {mode === "focus" ? "Focused" : "Focus on this object"}<span>F</span>
              </button>
            )}
          </section>

          <details open>
            <summary>Overview</summary>
            {binding.kind === "object" && (
              <dl className="inspector-facts">
                <div><dt>Object</dt><dd>{TYPE_COPY[binding.object.objectType]}</dd></div>
                <div><dt>Importance</dt><dd>{binding.object.importance.level} · {binding.object.importance.score}</dd></div>
                <div><dt>Technology</dt><dd>{String(binding.object.metadata.technology || "Not declared")}</dd></div>
              </dl>
            )}
            {binding.kind === "relationship" && (
              <div className="inspector-endpoints">
                <button onClick={() => binding.source && onSelect({ kind: "object", id: binding.source.id })} type="button"><small>From</small><strong>{binding.source?.name ?? binding.relationship.sourceObjectId}</strong></button>
                <span>→</span>
                <button onClick={() => binding.target && onSelect({ kind: "object", id: binding.target.id })} type="button"><small>To</small><strong>{binding.target?.name ?? binding.relationship.targetObjectId}</strong></button>
              </div>
            )}
            {binding.kind === "flow" && <p>{binding.flow.steps.length} steps across {binding.objects.length} objects and {new Set(binding.objects.map((object) => object.regionId)).size} regions.</p>}
          </details>

          <details open={binding.kind !== "flow"}>
            <summary>Relations</summary>
            {binding.kind === "object" && (
              <>
                <small className="inspector-section-label">Incoming · {binding.incoming.length}</small>
                <RelationshipList direction="in" onSelect={onSelect} relationships={binding.incoming} />
                <small className="inspector-section-label">Outgoing · {binding.outgoing.length}</small>
                <RelationshipList direction="out" onSelect={onSelect} relationships={binding.outgoing} />
              </>
            )}
            {binding.kind === "relationship" && <p>{binding.flows.length > 0 ? `Used by ${binding.flows.map((flow) => flow.name).join(", ")}.` : "Not part of a named Flow."}</p>}
            {binding.kind === "flow" && (
              <div className="inspector-object-list">
                {binding.objects.map((object, index) => <button key={object.id} onClick={() => onSelect({ kind: "object", id: object.id })} type="button"><b>{index + 1}</b><span>{object.name}</span></button>)}
              </div>
            )}
          </details>

          <details open={binding.kind === "flow"}>
            <summary>Runtime &amp; Activity</summary>
            {binding.kind === "flow" ? (
              <ol className="inspector-flow-steps">
                {binding.flow.steps.map((step) => (
                  <li key={step.id}>
                    <b>{step.sequence}</b>
                    <div><strong>{step.title}</strong><span>{step.action || step.role}</span></div>
                  </li>
                ))}
              </ol>
            ) : <p>Runtime overlay is not attached. Showing declared architecture state.</p>}
          </details>

          {binding.kind === "object" && binding.flows.length > 0 && (
            <details>
              <summary>Input / Output</summary>
              <div className="inspector-flow-list">
                {binding.flows.map((flow) => <button key={flow.id} onClick={() => onSelect({ kind: "flow", id: flow.id })} type="button"><strong>{flow.name}</strong><span>{flow.steps.length} steps</span></button>)}
              </div>
            </details>
          )}

          <details>
            <summary>Advanced / Raw</summary>
            <pre>{JSON.stringify(binding.raw, null, 2)}</pre>
          </details>
        </>
      )}
    </aside>
  );
}

