import { spawn } from "node:child_process";
import { readFileSync } from "node:fs";

const payloadFile = process.argv[2];
const { tool, args } = JSON.parse(readFileSync(payloadFile, "utf8"));

const child = spawn("prax-mcp", [], { stdio: ["pipe", "pipe", "inherit"], shell: process.platform === "win32" });
let out = "";
child.stdout.on("data", (chunk) => { out += chunk; });
child.on("close", () => {
  for (const line of out.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    try {
      const message = JSON.parse(trimmed);
      if (message.id === 2) {
        const content = message.result?.content;
        if (Array.isArray(content)) {
          for (const part of content) console.log(part.type === "text" ? part.text : JSON.stringify(part));
        } else {
          console.log(JSON.stringify(message, null, 1));
        }
      }
    } catch { /* line from server logs */ }
  }
});

const send = (message) => child.stdin.write(JSON.stringify(message) + "\n");
send({ jsonrpc: "2.0", id: 1, method: "initialize", params: { protocolVersion: "2024-11-05", capabilities: {}, clientInfo: { name: "prax-drive", version: "0.1" } } });
send({ jsonrpc: "2.0", method: "notifications/initialized" });
send({ jsonrpc: "2.0", id: 2, method: "tools/call", params: { name: tool, arguments: args } });
child.stdin.end();
setTimeout(() => { child.kill(); process.exit(0); }, 30000).unref();

