  input: unknown,
  context: DecisionValidationContext,
): ArtifactValidation<DesignDecisions> {
  const parsed = DesignDecisionsSchema.safeParse(input);
  if (!parsed.success) {
    return {
      status: "RETRY",
      issues: zodIssues(parsed.error),
      warnings: [],
    };
  }
