"use client";

import { useState } from "react";
import ArchitectureCanvas from "../architecture/architecture-canvas";
import { CANVAS_FIXTURES, type CanvasFixtureName } from "../architecture/fixtures";

export default function FixtureWorkbench() {
  const [fixtureName, setFixtureName] = useState<CanvasFixtureName>("small");
  const graph = CANVAS_FIXTURES[fixtureName];
  return (
    <main className="architecture-page canvas-shell fixture-shell">
      <aside className="canvas-nav-rail" aria-label="Fixture navigation">
        <span className="rail-brand" aria-label="Canvas Engine"><span aria-hidden="true"><i /><i /><i /></span></span>
        <nav><span className="fixture-rail-label">QA</span></nav>
      </aside>
      <section className="canvas-workspace">
        <header className="canvas-contextbar">
          <div>
            <select aria-label="Stress fixture" onChange={(event) => setFixtureName(event.target.value as CanvasFixtureName)} value={fixtureName}>
              {Object.keys(CANVAS_FIXTURES).map((name) => <option key={name} value={name}>{name[0].toUpperCase()}{name.slice(1)} fixture</option>)}
            </select>
            <span>Canvas Engine v1 · Stress Workbench</span>
          </div>
          <div><span className="context-revision">{graph.objects.length} O / {graph.relationships.length} R</span><span className="context-readonly">Fixture</span></div>
        </header>
        <ArchitectureCanvas graphOverride={graph} />
      </section>
    </main>
  );
}

