import assert from "node:assert/strict";
import { register } from "node:module";
import test from "node:test";

register("./cloudflare-loader.mjs", import.meta.url);

const {
  CANVAS_FIXTURES,
  COMPLEX_CANVAS_FIXTURE,
  LARGE_CANVAS_FIXTURE,
  MEDIUM_CANVAS_FIXTURE,
  SMALL_CANVAS_FIXTURE,
} = await import("../app/architecture/fixtures.ts");
const { deriveCanvasView, semanticZoomLevel, visibleObjectIds } = await import("../app/architecture/interaction.ts");
const { bindInspector } = await import("../app/architecture/inspector-binding.ts");
const { layoutSemanticGraph, measureLayoutStability } = await import("../app/architecture/layout.ts");
const { adaptArchitectureToSemanticGraph } = await import("../app/architecture/semantic-adapter.ts");
const { validateSemanticGraph } = await import("../app/architecture/semantic-graph.ts");

function overlap(left, right, padding = 0) {
  return left.x < right.x + right.width + padding
    && left.x + left.width + padding > right.x
    && left.y < right.y + right.height + padding
    && left.y + left.height + padding > right.y;
}

function segmentEntersRect(start, end, rect, inset = 2) {
  const left = rect.x + inset;
  const right = rect.x + rect.width - inset;
  const top = rect.y + inset;
  const bottom = rect.y + rect.height - inset;
  if (Math.abs(start.x - end.x) < .01) {
    const minY = Math.min(start.y, end.y);
    const maxY = Math.max(start.y, end.y);
    return start.x > left && start.x < right && maxY > top && minY < bottom;
  }
  if (Math.abs(start.y - end.y) < .01) {
    const minX = Math.min(start.x, end.x);
    const maxX = Math.max(start.x, end.x);
    return start.y > top && start.y < bottom && maxX > left && minX < right;
  }
  return false;
}

test("ships exact reusable stress fixture budgets and difficult topology", () => {
  assert.deepEqual(
    Object.fromEntries(Object.entries(CANVAS_FIXTURES).map(([name, graph]) => [name, [graph.objects.length, graph.relationships.length]])),
    { small: [15, 20], medium: [40, 70], large: [100, 180], complex: [64, 124] },
  );
  for (const graph of Object.values(CANVAS_FIXTURES)) assert.deepEqual(validateSemanticGraph(graph), []);

  assert.ok(COMPLEX_CANVAS_FIXTURE.regions.some((region) => {
    const parent = COMPLEX_CANVAS_FIXTURE.regions.find((candidate) => candidate.id === region.parentRegionId);
    return Boolean(parent?.parentRegionId);
  }), "Complex fixture must contain nested Regions");
  assert.ok(COMPLEX_CANVAS_FIXTURE.objects.some((object) => object.name.length > 60), "Complex fixture must include long labels");
  assert.deepEqual(new Set(COMPLEX_CANVAS_FIXTURE.relationships.map((relationship) => relationship.relationshipType)), new Set(["data", "control", "event", "dependency", "external"]));

  const degree = new Map(COMPLEX_CANVAS_FIXTURE.objects.map((object) => [object.id, 0]));
  for (const relationship of COMPLEX_CANVAS_FIXTURE.relationships) {
    degree.set(relationship.sourceObjectId, (degree.get(relationship.sourceObjectId) ?? 0) + 1);
    degree.set(relationship.targetObjectId, (degree.get(relationship.targetObjectId) ?? 0) + 1);
  }
  assert.ok([...degree.values()].some((value) => value === 0), "Complex fixture must preserve an isolated object");
  assert.ok(Math.max(...degree.values()) >= 16, "Complex fixture must exercise high fan-in or fan-out");
  assert.ok(COMPLEX_CANVAS_FIXTURE.relationships.some((relationship) => {
    const source = COMPLEX_CANVAS_FIXTURE.objects.find((object) => object.id === relationship.sourceObjectId);
    const target = COMPLEX_CANVAS_FIXTURE.objects.find((object) => object.id === relationship.targetObjectId);
    return source?.regionId !== target?.regionId;
  }), "Complex fixture must include cross-region relationships");
  assert.ok(COMPLEX_CANVAS_FIXTURE.flows.length >= 3, "Complex fixture must include multiple first-class Flows");
});

test("adapts canonical Architecture records into a renderer-independent Semantic Graph", () => {
  const row = { id: "row", projectId: "p", changeId: "c", knowledgeState: "CONFIRMED", lifecycleStatus: "ACTIVE", validFromRevision: 7, validToRevision: null, sourceObservationId: "obs" };
  const entities = [
    { ...row, entityKey: "domain", entityType: "Domain", name: "Control Plane", summary: "Boundary", parentEntityKey: null, technology: "", repositoryRefsJson: "[]" },
    { ...row, entityKey: "service", entityType: "Component", name: "Intent Service", summary: "Accepts intent", parentEntityKey: "domain", technology: "TypeScript", repositoryRefsJson: "[]" },
    { ...row, entityKey: "agent", entityType: "Agent", name: "Maintenance Agent", summary: "Executes a change", parentEntityKey: "domain", technology: "Agent runtime", repositoryRefsJson: "[]" },
    { ...row, entityKey: "store", entityType: "DataEntity", name: "Evidence Store", summary: "Persists evidence", parentEntityKey: "domain", technology: "D1", repositoryRefsJson: "[]" },
    { ...row, entityKey: "github", entityType: "Interface", name: "GitHub External API", summary: "Repository boundary", parentEntityKey: "domain", technology: "HTTPS", repositoryRefsJson: "[]" },
  ];
  const relations = [{
    ...row,
    relationKey: "service-agent",
    sourceEntityKey: "service",
    targetEntityKey: "agent",
    relationType: "calls",
    label: "delegates",
    summary: "Delegates the bounded change",
    evidenceRefsJson: "[]",
  }];
  const flows = [{ ...row, flowKey: "change-flow", name: "Intent to evidence", summary: "Bounded change", trigger: "Intent", outcome: "Evidence" }];
  const step = (stepKey, sequence, entityKey, nextStepKeys) => ({
    ...row,
    flowKey: "change-flow",
    stepKey,
    sequence,
    entityKey,
    role: sequence === 1 ? "entry" : sequence === 3 ? "exit" : "transformer",
    title: stepKey,
    inputsJson: "[]",
    action: stepKey,
    outputsJson: "[]",
    stateReadsJson: "[]",
    stateWritesJson: "[]",
    failureModesJson: "[]",
    nextStepKeysJson: JSON.stringify(nextStepKeys),
  });
  const graph = adaptArchitectureToSemanticGraph({
    projectId: "p",
    projectName: "Project",
    revision: 7,
    entities,
    relations,
    flows,
    flowSteps: [step("one", 1, "service", ["two"]), step("two", 2, "agent", ["three"]), step("three", 3, "store", [])],
  });
  assert.equal(graph.regions.length, 1);
  assert.deepEqual(graph.objects.map((object) => object.objectType), ["agent", "external", "service", "storage"]);
  assert.equal(graph.relationships.find((relationship) => relationship.id === "service-agent")?.relationshipType, "control");
  assert.ok(graph.relationships.some((relationship) => relationship.metadata.synthetic === true), "Missing Flow adjacency must become a semantic Relationship");
  assert.deepEqual(graph.flows[0].objectIds, ["service", "agent", "store"]);
  assert.equal(graph.flows[0].relationshipIds.length, 2);

  const objectBinding = bindInspector(graph, { kind: "object", id: "agent" });
  const relationshipBinding = bindInspector(graph, { kind: "relationship", id: "service-agent" });
  assert.equal(objectBinding?.kind, "object");
  assert.equal(objectBinding?.location, "Control Plane");
  assert.equal(relationshipBinding?.kind, "relationship");
  assert.equal(relationshipBinding?.location, "Intent Service → Maintenance Agent");
});

test("implements discrete semantic zoom and readable Focus / Trace emphasis", () => {
  assert.equal(semanticZoomLevel(.3), "landscape");
  assert.equal(semanticZoomLevel(.6), "architecture");
  assert.equal(semanticZoomLevel(1), "component");
  assert.equal(semanticZoomLevel(1.4), "operational");

  const landscape = deriveCanvasView(LARGE_CANVAS_FIXTURE, {
    mode: "browse",
    selection: null,
    activeFlowId: null,
    zoom: .24,
    searchQuery: "",
  });
  const landscapeObjects = visibleObjectIds(LARGE_CANVAS_FIXTURE, landscape);
  assert.ok(landscapeObjects.size < LARGE_CANVAS_FIXTURE.objects.length, "Landscape must reduce Objects after reducing detail");
  assert.ok(landscapeObjects.size >= 2, "Landscape must retain important named Objects");

  const selectedObject = SMALL_CANVAS_FIXTURE.objects[0];
  const focus = deriveCanvasView(SMALL_CANVAS_FIXTURE, {
    mode: "focus",
    selection: { kind: "object", id: selectedObject.id },
    activeFlowId: null,
    zoom: .9,
    searchQuery: "",
  });
  assert.equal(focus.objectEmphasis.get(selectedObject.id), "primary");
  assert.ok([...focus.objectEmphasis.values()].includes("context"), "Focus must retain readable context");
  assert.ok([...focus.objectEmphasis.values()].includes("muted"), "Focus must reduce unrelated topology");
  assert.ok([...focus.relationshipEmphasis.values()].includes("active"));

  const flow = SMALL_CANVAS_FIXTURE.flows[0];
  const trace = deriveCanvasView(SMALL_CANVAS_FIXTURE, {
    mode: "trace",
    selection: { kind: "flow", id: flow.id },
    activeFlowId: flow.id,
    zoom: .9,
    searchQuery: "",
  });
  for (const objectId of flow.objectIds) assert.equal(trace.objectEmphasis.get(objectId), "primary");
  for (const relationshipId of flow.relationshipIds) assert.equal(trace.relationshipEmphasis.get(relationshipId), "active");
  assert.ok([...trace.relationshipEmphasis.values()].includes("suppressed"));
});

test("ELK compound layout is deterministic, non-overlapping and obstacle-safe", { timeout: 60_000 }, async () => {
  const durations = {};
  for (const [name, graph] of Object.entries(CANVAS_FIXTURES)) {
    const layout = await layoutSemanticGraph(graph);
    durations[name] = layout.durationMs;
    assert.equal(Object.keys(layout.objectRects).length, graph.objects.length, `${name} must lay out every Object`);
    assert.equal(Object.keys(layout.regionRects).length, graph.regions.length, `${name} must lay out every Region`);
    assert.equal(Object.keys(layout.relationshipRoutes).length, graph.relationships.length, `${name} must route every Relationship`);

    const rects = Object.values(layout.objectRects);
    for (let leftIndex = 0; leftIndex < rects.length; leftIndex += 1) {
      for (let rightIndex = leftIndex + 1; rightIndex < rects.length; rightIndex += 1) {
        assert.equal(overlap(rects[leftIndex], rects[rightIndex], 2), false, `${name}: Objects ${rects[leftIndex].id} and ${rects[rightIndex].id} overlap`);
      }
    }

    for (const relationship of graph.relationships) {
      const route = layout.relationshipRoutes[relationship.id];
      assert.ok(route.points.length >= 2, `${name}: ${relationship.id} needs a usable route`);
      for (let pointIndex = 0; pointIndex < route.points.length - 1; pointIndex += 1) {
        const start = route.points[pointIndex];
        const end = route.points[pointIndex + 1];
        assert.ok(Math.abs(start.x - end.x) < .01 || Math.abs(start.y - end.y) < .01, `${name}: ${relationship.id} must be orthogonal`);
        for (const object of graph.objects) {
          if (object.id === relationship.sourceObjectId || object.id === relationship.targetObjectId) continue;
          assert.equal(segmentEntersRect(start, end, layout.objectRects[object.id]), false, `${name}: ${relationship.id} crosses ${object.id}`);
        }
      }
      if (route.labelPoint) {
        for (const object of graph.objects) {
          const rect = layout.objectRects[object.id];
          assert.equal(route.labelPoint.x > rect.x && route.labelPoint.x < rect.x + rect.width && route.labelPoint.y > rect.y && route.labelPoint.y < rect.y + rect.height, false, `${name}: ${relationship.id} label covers ${object.id}`);
        }
      }
    }
  }
  assert.ok(durations.large < 15_000, `Large fixture layout should remain interactive, received ${durations.large}ms`);

  const first = await layoutSemanticGraph(MEDIUM_CANVAS_FIXTURE);
  const repeated = await layoutSemanticGraph(MEDIUM_CANVAS_FIXTURE, { previousLayout: first });
  assert.deepEqual(repeated.objectRects, first.objectRects, "Repeated graph opens must keep identical object placement");
  assert.deepEqual(repeated.relationshipRoutes, first.relationshipRoutes, "Repeated graph opens must keep identical routes");

  const extraObject = {
    ...MEDIUM_CANVAS_FIXTURE.objects[0],
    id: "medium:object:added",
    name: "New bounded service",
    layoutHints: { order: MEDIUM_CANVAS_FIXTURE.objects.length },
  };
  const extended = { ...MEDIUM_CANVAS_FIXTURE, id: "fixture:medium:extended", objects: [...MEDIUM_CANVAS_FIXTURE.objects, extraObject] };
  const extendedLayout = await layoutSemanticGraph(extended, { previousLayout: first });
  const stability = measureLayoutStability(first, extendedLayout);
  assert.ok(stability.relativeOrderRetention >= .9, `Minor additions must retain relative order, received ${stability.relativeOrderRetention}`);
});

test("fixture performance envelope covers the acceptance scales", async () => {
  const results = [];
  for (const graph of [SMALL_CANVAS_FIXTURE, MEDIUM_CANVAS_FIXTURE, LARGE_CANVAS_FIXTURE]) {
    const layout = await layoutSemanticGraph(graph);
    results.push({ objects: graph.objects.length, relationships: graph.relationships.length, layoutMs: layout.durationMs });
  }
  console.info("Canvas Engine layout envelope", results);
  assert.deepEqual(results.map((result) => result.objects), [15, 40, 100]);
});

