  suffixStart: {x,y}, blockB (packed), sideQ,
  geometry: { columnGutterXs: number[]; rowGutterYs: number[]; gutterX: number; gutterY: number },
): { points: Array<{x,y}>; labelPoint: {x,y} } {
  const outward = (side) => side === "left" ? {x:-1,y:0} : side === "right" ? {x:1,y:0} : side === "top" ? {x:0,y:-1} : {x:0,y:1};
  const offP = outward(sideP), offQ = outward(sideQ);
  const stepP = sideP === "left" || sideP === "right" ? geometry.gutterX / 2 : geometry.gutterY / 2;
  const stepQ = ...;
