  const q1 = { x: suffixStart.x + offQ.x * stepQ, y: suffixStart.y + offQ.y * stepQ };
  const rgyP = (sideP === "top" || sideP === "bottom") ? p1.y : nearest(geometry.rowGutterYs, p1.y);
  const cgxQ = (sideQ === "left" || sideQ === "right") ? q1.x : nearest(geometry.columnGutterXs, q1.x);
  const points = [
