function compactOrthogonalPoints(points: Array<{ x: number; y: number }>) {
  const result: Array<{ x: number; y: number }> = [];
  for (const point of points) {
    const last = result.at(-1);
    if (last && Math.abs(last.x - point.x) < .01 && Math.abs(last.y - point.y) < .01) continue;
    result.push(point);
  }
  for (let index = result.length - 2; index > 0; index -= 1) {
    const previous = result[index - 1];
    const current = result[index];
    const next = result[index + 1];
    if (Math.abs(previous.x - current.x) < .01 && Math.abs(current.x - next.x) < .01) result.splice(index, 1);
    else if (Math.abs(previous.y - current.y) < .01 && Math.abs(current.y - next.y) < .01) result.splice(index, 1);
