function bridgeAcrossGutters(
  prefixEnd: { x: number; y: number },
  sourceBlock: CompositionBlock,
  suffixStart: { x: number; y: number },
  targetBlock: CompositionBlock,
  geometry: CompositionGeometry,
) {
  const sideSource = boundarySide(sourceBlock.packed, prefixEnd);
  const sideTarget = boundarySide(targetBlock.packed, suffixStart);
  const offset = (side: BoundarySide) => {
    if (side === "left") return { x: -ROOT_COMPOSITION.gutterX / 2, y: 0 };
    if (side === "right") return { x: ROOT_COMPOSITION.gutterX / 2, y: 0 };
    if (side === "top") return { x: 0, y: -ROOT_COMPOSITION.gutterY / 2 };
    return { x: 0, y: ROOT_COMPOSITION.gutterY / 2 };
  };
  const offsetSource = offset(sideSource);
  const offsetTarget = offset(sideTarget);
  const outSource = { x: prefixEnd.x + offsetSource.x, y: prefixEnd.y + offsetSource.y };
  const outTarget = { x: suffixStart.x + offsetTarget.x, y: suffixStart.y + offsetTarget.y };
  const horizontalSource = sideSource === "left" || sideSource === "right";
  const horizontalTarget = sideTarget === "left" || sideTarget === "right";
  const rowRunY = horizontalSource ? nearestValue(geometry.rowGutterYs, outSource.y) : outSource.y;
  const columnRunX = horizontalTarget ? outTarget.x : nearestValue(geometry.columnGutterXs, outTarget.x);
  const points = compactOrthogonalPoints([
    prefixEnd,
    outSource,
    { x: outSource.x, y: rowRunY },
    { x: columnRunX, y: rowRunY },
    { x: columnRunX, y: outTarget.y },
    outTarget,
    suffixStart,
  ]);
  return {
    points,
    labelPoint: { x: (outSource.x + columnRunX) / 2, y: rowRunY },
  };
}

function composeTopLevelBlocks(graph: SemanticGraph, layout: CanvasLayout): CanvasLayout {
  const rootRegions = graph.regions
    .filter((region) => !region.parentRegionId)
    .sort((left, right) => (left.order ?? 0) - (right.order ?? 0) || left.id.localeCompare(right.id));
  let level: "root" | "region" = "root";
  let containerId: string | null = null;
  let blockRegions: SemanticRegion[] = rootRegions;
  if (rootRegions.length === 1) {
    const children = graph.regions
      .filter((region) => region.parentRegionId === rootRegions[0].id)
      .sort((left, right) => (left.order ?? 0) - (right.order ?? 0) || left.id.localeCompare(right.id));
    if (children.length >= 2) {
      level = "region";
      containerId = rootRegions[0].id;
      blockRegions = children;
    }
  }
  if (blockRegions.length < 2) return layout;

  const regionById = new Map(graph.regions.map((region) => [region.id, region]));
  const childRegions = new Map<string, SemanticRegion[]>();
  for (const region of graph.regions) {
    if (!region.parentRegionId) continue;
