    const rect = layout.regionRects[region.id];
    if (!rect || memberObjectIds.size === 0) continue;
    blocks.push({
      id: region.id,
      residual: false,
      memberRegionIds,
      memberObjectIds,
      original: { id: region.id, x: rect.x, y: rect.y, width: rect.width, height: rect.height },
      packed: { x: 0, y: 0, width: rect.width, height: rect.height },
      column: 0,
      row: 0,
      delta: { x: 0, y: 0 },
    });
  }

  const containerObjectIds = new Set(
    graph.objects.filter((object) => (level === "region" ? object.regionId === containerId : false)).map((object) => object.id),
  );
