    const rects = [...containerObjectIds].map((id) => layout.objectRects[id]).filter((rect): rect is LayoutRect => Boolean(rect));
    if (rects.length > 0) {
      const left = Math.min(...rects.map((rect) => rect.x)) - 26;
      const top = Math.min(...rects.map((rect) => rect.y)) - 26;
      const right = Math.max(...rects.map((rect) => rect.x + rect.width)) + 26;
      const bottom = Math.max(...rects.map((rect) => rect.y + rect.height)) + 26;
      blocks.push({
        id: `${containerId ?? "root"}:residual`,
        residual: true,
        memberRegionIds: new Set<string>(),
        memberObjectIds: containerObjectIds,
        original: { id: "residual", x: left, y: top, width: right - left, height: bottom - top },
        packed: { x: 0, y: 0, width: right - left, height: bottom - top },
        column: 0,
        row: 0,
        delta: { x: 0, y: 0 },
      });
    }
  }
  if (blocks.length < 2) return layout;

  const ordered = [...blocks].sort((left, right) =>
    left.original.y - right.original.y || left.original.x - right.original.x || left.id.localeCompare(right.id));
  const columns = compositionColumns(ordered.length);
  const columnWidths = Array.from({ length: columns }, (_, column) =>
    Math.max(...ordered.filter((_, index) => index % columns === column).map((block) => block.original.width), 0));
  const rowCount = Math.ceil(ordered.length / columns);
  const rowHeights = Array.from({ length: rowCount }, (_, row) =>
    Math.max(...ordered.filter((_, index) => Math.floor(index / columns) === row).map((block) => block.original.height), 0));

  const columnXs: number[] = [];
  let cursorX = 0;
  for (let column = 0; column < columns; column += 1) {
    columnXs.push(cursorX);
    cursorX += columnWidths[column] + ROOT_COMPOSITION.gutterX;
  }
  const rowYs: number[] = [];
  let cursorY = 0;
  for (let row = 0; row < rowCount; row += 1) {
    rowYs.push(cursorY);
    cursorY += rowHeights[row] + ROOT_COMPOSITION.gutterY;
  }

  ordered.forEach((block, index) => {
    block.column = index % columns;
    block.row = Math.floor(index / columns);
    block.packed = { ...block.packed, x: columnXs[block.column], y: rowYs[block.row] };
    block.delta = { x: block.packed.x - block.original.x, y: block.packed.y - block.original.y };
  });

  const objectRects: Record<string, LayoutRect> = { ...layout.objectRects };
  const regionRects: Record<string, RegionLayoutRect> = { ...layout.regionRects };
  const blockOfObject = new Map<string, CompositionBlock>();
  for (const block of ordered) {
    for (const objectId of block.memberObjectIds) {
      blockOfObject.set(objectId, block);
      const rect = objectRects[objectId];
      if (rect) objectRects[objectId] = { ...rect, x: rect.x + block.delta.x, y: rect.y + block.delta.y };
    }
    if (block.residual) continue;
    for (const regionId of block.memberRegionIds) {
      const rect = regionRects[regionId];
      if (rect) regionRects[regionId] = { ...rect, x: rect.x + block.delta.x, y: rect.y + block.delta.y };
    }
  }

  const packedRight = Math.max(...ordered.map((block) => block.packed.x + block.packed.width));
  const packedBottom = Math.max(...ordered.map((block) => block.packed.y + block.packed.height));
  if (level === "region" && containerId) {
    const container = regionRects[containerId];
    if (container) {
      regionRects[containerId] = {
        ...container,
        x: -26,
        y: -54,
        width: packedRight + 52,
        height: packedBottom + 80,
      };
    }
  }

  const columnGutterXs = [
    columnXs[0] - ROOT_COMPOSITION.gutterX / 2,
    ...Array.from({ length: columns - 1 }, (_, index) =>
      columnXs[index] + columnWidths[index] + ROOT_COMPOSITION.gutterX / 2),
    columnXs[columns - 1] + columnWidths[columns - 1] + ROOT_COMPOSITION.gutterX / 2,
  ];
  const rowGutterYs = [
    rowYs[0] - ROOT_COMPOSITION.gutterY / 2,
    ...Array.from({ length: rowCount - 1 }, (_, index) =>
      rowYs[index] + rowHeights[index] + ROOT_COMPOSITION.gutterY / 2),
    rowYs[rowCount - 1] + rowHeights[rowCount - 1] + ROOT_COMPOSITION.gutterY / 2,
  ];
  const geometry: CompositionGeometry = { columnGutterXs, rowGutterYs };

  const relationshipRoutes: Record<string, RelationshipRoute> = {};
  for (const relationship of graph.relationships) {
    const route = layout.relationshipRoutes[relationship.id];
    if (!route) continue;
    const sourceBlock = blockOfObject.get(relationship.sourceObjectId);
    const targetBlock = blockOfObject.get(relationship.targetObjectId);
    if (!sourceBlock || !targetBlock) {
      relationshipRoutes[relationship.id] = route;
      continue;
    }
    if (sourceBlock === targetBlock) {
      relationshipRoutes[relationship.id] = {
        ...route,
        points: route.points.map((point) => ({ x: point.x + sourceBlock.delta.x, y: point.y + sourceBlock.delta.y })),
        labelPoint: route.labelPoint
          ? { x: route.labelPoint.x + sourceBlock.delta.x, y: route.labelPoint.y + sourceBlock.delta.y }
          : undefined,
      };
      continue;
    }
    let prefixEnd = -1;
    for (let index = 0; index < route.points.length; index += 1) {
      if (!strictlyInside(sourceBlock.original, route.points[index])) {
        prefixEnd = index;
        break;
      }
    }
    let suffixStart = -1;
    for (let index = route.points.length - 1; index >= 0; index -= 1) {
      if (!looselyInside(targetBlock.original, route.points[index])) {
        suffixStart = index + 1;
        break;
      }
      suffixStart = index;
    }
    if (prefixEnd < 1 || suffixStart < 0 || prefixEnd > suffixStart) continue;

    const translatedPrefix = route.points.slice(0, prefixEnd + 1)
      .map((point) => ({ x: point.x + sourceBlock.delta.x, y: point.y + sourceBlock.delta.y }));
    const translatedSuffix = route.points.slice(suffixStart)
      .map((point) => ({ x: point.x + targetBlock.delta.x, y: point.y + targetBlock.delta.y }));
    const bridge = bridgeAcrossGutters(
      translatedPrefix.at(-1)!,
      sourceBlock,
      translatedSuffix[0],
      targetBlock,
      geometry,
    );
    relationshipRoutes[relationship.id] = {
      ...route,
      points: compactOrthogonalPoints([...translatedPrefix, ...bridge.points, ...translatedSuffix]),
      labelPoint: bridge.labelPoint,
    };
  }

  const width = Math.max(...Object.values(regionRects).map((rect) => rect.x + rect.width)) + 42;
  const height = Math.max(...Object.values(regionRects).map((rect) => rect.y + rect.height)) + 42;
  return {
    ...layout,
    width,
    height,
    objectRects,
    regionRects,
    relationshipRoutes,
    composition: {
      level,
      containerId,
      columns,
      blockIds: ordered.map((block) => block.id),
    },
  };
}

