import { register } from "node:module";
register("./cloudflare-loader.mjs", import.meta.url);
const { CANVAS_FIXTURES } = await import("../app/architecture/fixtures.ts");
const { layoutSemanticGraph, compositionColumns } = await import("../app/architecture/layout.ts");

function overlap(left, right, padding = 0) {
  return left.x < right.x + right.width + padding && left.x + left.width + padding > right.x
    && left.y < right.y + right.height + padding && left.y + left.height + padding > right.y;
}
function segmentEntersRect(start, end, rect, inset = 2) {
  const left = rect.x + inset, right = rect.x + rect.width - inset, top = rect.y + inset, bottom = rect.y + rect.height - inset;
  if (Math.abs(start.x - end.x) < .01) {
    const minY = Math.min(start.y, end.y), maxY = Math.max(start.y, end.y);
    return start.x > left && start.x < right && maxY > top && minY < bottom;
  }
  if (Math.abs(start.y - end.y) < .01) {
    const minX = Math.min(start.x, end.x), maxX = Math.max(start.x, end.x);
    return start.y > top && start.y < bottom && maxX > left && minX < right;
  }
  return false;
}

for (const [name, graph] of Object.entries(CANVAS_FIXTURES)) {
  const layout = await layoutSemanticGraph(graph);
  const composition = layout.composition;
  const blocks = (composition?.blockIds ?? []).map((id) => layout.regionRects[id] ?? { x: 0, y: 0, width: 0, height: 0, id });
  const rows = new Set(blocks.map((rect) => Math.round(rect.y / 80)));
  let missingRoutes = 0, nonOrtho = 0, obstacle = 0, labelHits = 0, regionOverlap = 0;
  for (let i = 0; i < blocks.length; i++) for (let j = i + 1; j < blocks.length; j++) {
    if (overlap(blocks[i], blocks[j], 8)) regionOverlap++;
  }
  for (const relationship of graph.relationships) {
    const route = layout.relationshipRoutes[relationship.id];
    if (!route || route.points.length < 2) { missingRoutes++; continue; }
    for (let k = 0; k < route.points.length - 1; k++) {
      const start = route.points[k], end = route.points[k + 1];
      if (!(Math.abs(start.x - end.x) < .01 || Math.abs(start.y - end.y) < .01)) nonOrtho++;
      for (const object of graph.objects) {
        if (object.id === relationship.sourceObjectId || object.id === relationship.targetObjectId) continue;
        if (segmentEntersRect(start, end, layout.objectRects[object.id])) obstacle++;
      }
    }
    if (route.labelPoint) {
      for (const object of graph.objects) {
        const rect = layout.objectRects[object.id];
        if (route.labelPoint.x > rect.x && route.labelPoint.x < rect.x + rect.width && route.labelPoint.y > rect.y && route.labelPoint.y < rect.y + rect.height) labelHits++;
      }
    }
  }
  const rects = Object.values(layout.objectRects);
  let objectOverlap = 0;
  for (let i = 0; i < rects.length; i++) for (let j = i + 1; j < rects.length; j++) if (overlap(rects[i], rects[j], 2)) objectOverlap++;
  console.log(name, {
    blocks: blocks.length, rows: rows.size, columns: composition?.columns, expectedColumns: compositionColumns(blocks.length),
    canvas: `${Math.round(layout.width)}x${Math.round(layout.height)}`, aspect: (layout.width / layout.height).toFixed(2),
    missingRoutes, nonOrtho, obstacle, labelHits, regionOverlap, objectOverlap,
  });
}

