const refitForDockChange = useCallback(() => {
  const instance = instanceRef.current;
  if (!instance) return;
  if (interaction.mode === "trace" && interaction.activeFlowId) {
    const flow = graph.flows.find(f => f.id === interaction.activeFlowId);
    const ids = new Set(flow?.objectIds ?? []);
    const targetNodes = instance.getNodes().filter(n => ids.has(n.id));
    if (targetNodes.length > 0) void instance.fitView({ nodes: targetNodes, padding: .3, duration: 320, minZoom: ARCHITECTURE_ZOOM_FLOOR, maxZoom: 1.15 });
