  setNodes(projection.nodes);
  setEdges(projection.edges);
  const layoutIdentity = layout ? `${storageKey}:${layout.fingerprint}` : "";
  if (layoutIdentity && fittedLayoutRef.current !== layoutIdentity) {
    fittedLayoutRef.current = layoutIdentity;
    const timer = window.setTimeout(() => applyArchitectureCamera(), 60);
    return () => window.clearTimeout(timer);
  }
  return undefined;
}, [applyArchitectureCamera, layout, projection, setEdges, setNodes, storageKey]);

const docked = Boolean(inspectorBinding);
useEffect(() => {
  if (dockToggleRef.current === docked) return;
  dockToggleRef.current = docked;
  const timer = window.setTimeout(() => {
    const instance = instanceRef.current;
    if (!instance) return;
    if (interaction.mode === "trace" && interaction.activeFlowId) {
      const flowObjectIds = new Set(graph.flows.find((flow) => flow.id === interaction.activeFlowId)?.objectIds ?? []);
      const targetNodes = instance.getNodes().filter((node) => flowObjectIds.has(node.id));
      if (targetNodes.length > 0) {
        void instance.fitView({ nodes: targetNodes, padding: .3, duration: 320, minZoom: ARCHITECTURE_ZOOM_FLOOR, maxZoom: 1.15 });
        return;
      }
    }
    if ((interaction.mode === "focus" || interaction.mode === "inspect") && interaction.selection?.kind === "object") {
      const targetNodes = instance.getNodes().filter((node) => node.id === interaction.selection?.id);
      if (targetNodes.length > 0) {
        void instance.fitView({ nodes: targetNodes, padding: .35, duration: 320, minZoom: ARCHITECTURE_ZOOM_FLOOR, maxZoom: 1.15 });
        return;
      }
    }
    applyArchitectureCamera(320);
  }, 240);
  return () => window.clearTimeout(timer);
}, [applyArchitectureCamera, docked, graph.flows, interaction.activeFlowId, interaction.mode, interaction.selection]);

