"use client";

import {
  BaseEdge,
  EdgeLabelRenderer,
  getSmoothStepPath,
  type Edge,
  type EdgeProps,
} from "@xyflow/react";
import { useSmartEdgePath } from "@tisoap/react-flow-smart-edge";
import type { RelationshipEdgeData } from "./types";

export type ArchitectureFlowEdge = Edge<RelationshipEdgeData, "relationship">;

function roundedOrthogonalPath(points: Array<{ x: number; y: number }>, radius = 8) {
  if (points.length < 2) return "";
  let path = `M ${points[0].x} ${points[0].y}`;
  for (let index = 1; index < points.length - 1; index += 1) {
    const previous = points[index - 1];
    const current = points[index];
    const next = points[index + 1];
    const incomingLength = Math.hypot(current.x - previous.x, current.y - previous.y);
    const outgoingLength = Math.hypot(next.x - current.x, next.y - current.y);
    const corner = Math.min(radius, incomingLength / 2, outgoingLength / 2);
    if (!corner || (previous.x === current.x && current.x === next.x) || (previous.y === current.y && current.y === next.y)) {
      path += ` L ${current.x} ${current.y}`;
      continue;
    }
    const before = {
      x: current.x - ((current.x - previous.x) / incomingLength) * corner,
      y: current.y - ((current.y - previous.y) / incomingLength) * corner,
    };
    const after = {
      x: current.x + ((next.x - current.x) / outgoingLength) * corner,
      y: current.y + ((next.y - current.y) / outgoingLength) * corner,
    };
    path += ` L ${before.x} ${before.y} Q ${current.x} ${current.y} ${after.x} ${after.y}`;
  }
  const last = points.at(-1)!;
  return `${path} L ${last.x} ${last.y}`;
}

export default function RelationshipEdge(props: EdgeProps<ArchitectureFlowEdge>) {
  const smart = useSmartEdgePath({
    id: props.id,
    source: props.source,
    target: props.target,
    sourceX: props.sourceX,
    sourceY: props.sourceY,
    targetX: props.targetX,
    targetY: props.targetY,
    sourcePosition: props.sourcePosition,
    targetPosition: props.targetPosition,
    preset: "smoothstep",
    options: { gridRatio: 10, nodePadding: 18, borderRadius: 8 },
  });
  const fallback = getSmoothStepPath({
    sourceX: props.sourceX,
    sourceY: props.sourceY,
    sourcePosition: props.sourcePosition,
    targetX: props.targetX,
    targetY: props.targetY,
    targetPosition: props.targetPosition,
    borderRadius: 8,
  });
  const elkPath = props.data?.route?.points && props.data.route.points.length >= 2
    ? roundedOrthogonalPath(props.data.route.points)
    : "";
  const path = elkPath || (smart.route?.kind === "routed" ? smart.route.svgPathString : fallback[0]);
  const labelX = props.data?.route?.labelPoint?.x ?? (smart.route?.kind === "routed" ? smart.route.edgeCenterX : fallback[1]);
  const labelY = props.data?.route?.labelPoint?.y ?? (smart.route?.kind === "routed" ? smart.route.edgeCenterY : fallback[2]);
  const relationship = props.data?.relationship;
  const emphasis = props.data?.emphasis ?? "normal";
  const showLabel = emphasis === "active" || props.selected || props.data?.zoomLevel === "operational";
  const label = props.data?.flowPayload || relationship?.label || relationship?.relationshipType;
  const animate = emphasis === "active" && Boolean(props.data?.activeFlowName);

  return (
    <g className={`relationship-edge type-${relationship?.relationshipType ?? "dependency"} emphasis-${emphasis} ${props.selected ? "is-selected" : ""}`}>
      <BaseEdge
        id={props.id}
        interactionWidth={22}
        markerEnd={props.markerEnd}
        path={path}
        style={props.style}
      />
      {animate && (
        <circle className="flow-packet" r="4.5">
          <animateMotion dur="2.8s" path={path} repeatCount="indefinite" />
        </circle>
      )}
      {showLabel && label && (
        <EdgeLabelRenderer>
          <div
            className={`relationship-label nodrag nopan ${emphasis === "active" ? "active" : ""}`}
            style={{ transform: `translate(-50%, -50%) translate(${labelX}px,${labelY}px)` }}
            title={relationship?.summary || relationship?.label}
          >
            {props.data?.flowSequence !== undefined && <b>{props.data.flowSequence}</b>}
            <span>{label}</span>
          </div>
        </EdgeLabelRenderer>
      )}
    </g>
  );
}

"use client";

import {
  Background,
  BackgroundVariant,
  Controls,
  MiniMap,
  ReactFlow,
  type EdgeChange,
  type Node,
  type NodeChange,
  type ReactFlowInstance,
  type Viewport,
} from "@xyflow/react";
import { SmartEdgeProvider } from "@tisoap/react-flow-smart-edge";
import type { ReactNode } from "react";
import RelationshipEdge from "./architecture-edge";
import ObjectNode from "./architecture-node";
import CorridorEdge from "./corridor-edge";
import RegionNode from "./region-node";
import type { CanvasMode } from "./interaction";
import type { CanvasEdge, CanvasNode, CanvasObjectNode, CanvasRelationshipEdge } from "./projection";
import type { ObjectNodeData } from "./types";

const nodeTypes = { object: ObjectNode, region: RegionNode };
const edgeTypes = { relationship: RelationshipEdge, corridor: CorridorEdge };

type CanvasKernelProps = {
  nodes: CanvasNode[];
  edges: CanvasEdge[];
  mode: CanvasMode;
  onNodesChange: (changes: NodeChange<CanvasNode>[]) => void;
  onEdgesChange: (changes: EdgeChange<CanvasEdge>[]) => void;
  onInit: (instance: ReactFlowInstance<CanvasNode, CanvasEdge>) => void;
  onNodeClick: (node: CanvasObjectNode) => void;
  onEdgeClick: (edge: CanvasRelationshipEdge) => void;
  onNodeDragStop: (node: CanvasObjectNode) => void;
  onPaneClick: () => void;
  onViewportChange: (viewport: Viewport) => void;
  children?: ReactNode;
};

export default function ArchitectureCanvasKernel({
  nodes,
  edges,
  mode,
  onNodesChange,
  onEdgesChange,
  onInit,
  onNodeClick,
  onEdgeClick,
  onNodeDragStop,
  onPaneClick,
  onViewportChange,
  children,
}: CanvasKernelProps) {
  return (
    <SmartEdgeProvider
      nodes={nodes as Node[]}
      options={{
        preset: "smoothstep",
        routeOnlyWhenBlocked: false,
        routeWhileDragging: true,
        nodePadding: 18,
        gridRatio: 10,
        debounceMs: 16,
      }}
    >
      <ReactFlow<CanvasNode, CanvasEdge>
        className={`architecture-canvas-kernel mode-${mode}`}
        edges={edges}
        edgesReconnectable={false}
        edgeTypes={edgeTypes}
        elementsSelectable
        elevateEdgesOnSelect
        fitView
        maxZoom={1.85}
        minZoom={0.16}
        nodeTypes={nodeTypes}
        nodes={nodes}
        nodesConnectable={false}
        nodesDraggable
        onEdgeClick={(_, edge) => onEdgeClick(edge)}
        onEdgesChange={onEdgesChange}
        onInit={onInit}
        onMoveEnd={(_, viewport) => onViewportChange(viewport)}
        onNodeClick={(_, node) => { if (node.type === "object") onNodeClick(node as CanvasObjectNode); }}
        onNodeDragStop={(_, node) => { if (node.type === "object") onNodeDragStop(node as CanvasObjectNode); }}
        onNodesChange={onNodesChange}
        onPaneClick={onPaneClick}
        onlyRenderVisibleElements
        panOnDrag
        proOptions={{ hideAttribution: true }}
        selectionOnDrag={false}
        zoomOnDoubleClick={false}
      >
        <Background color="rgba(132,151,157,.24)" gap={28} size={1} variant={BackgroundVariant.Dots} />
        <Controls className="architecture-controls" showInteractive={false} />
        <MiniMap
          className="architecture-minimap"
          maskColor="rgba(9,14,17,.68)"
          nodeColor={(node) => node.type === "region" ? "rgba(118,139,145,.2)" : (node.data as ObjectNodeData | undefined)?.object.state.severity === "critical" ? "#bd7068" : "#688f89"}
          pannable
          zoomable
        />
        {children}
      </ReactFlow>
    </SmartEdgeProvider>
  );
}

