14	
15	function roundedOrthogonalPath(points: Array<{ x: number; y: number }>, radius = 8) {
16	  if (points.length < 2) return "";
17	  let path = `M ${points[0].x} ${points[0].y}`;
18	  for (let index = 1; index < points.length - 1; index += 1) {
19	    const previous = points[index - 1];
20	    const current = points[index];
21	    const next = points[index + 1];
22	    const incomingLength = Math.hypot(current.x - previous.x, current.y - previous.y);
23	    const outgoingLength = Math.hypot(next.x - current.x, next.y - current.y);
24	    const corner = Math.min(radius, incomingLength / 2, outgoingLength / 2);
25	    if (!corner || (previous.x === current.x && current.x === next.x) || (previous.y === current.y && current.y === next.y)) {
26	      path += ` L ${current.x} ${current.y}`;
27	      continue;
28	    }
29	    const before = {
30	      x: current.x - ((current.x - previous.x) / incomingLength) * corner,
31	      y: current.y - ((current.y - previous.y) / incomingLength) * corner,
32	    };
33	    const after = {
34	      x: current.x + ((next.x - current.x) / outgoingLength) * corner,
35	      y: current.y + ((next.y - current.y) / outgoingLength) * corner,
36	    };
37	    path += ` L ${before.x} ${before.y} Q ${current.x} ${current.y} ${after.x} ${after.y}`;
38	  }
39	  const last = points.at(-1)!;
40	  return `${path} L ${last.x} ${last.y}`;
41	}
