() => {
  const buttons = [...document.querySelectorAll(".react-flow__controls button")];
  const zoomOut = buttons.find((button) => button.title.toLowerCase().includes("zoom out"));
  const fit = document.querySelector(".canvas-command-actions button");
  const status = document.querySelector(".canvas-statusbar span")?.textContent;
  const out = { status, clicks: 0 };
  const transform = () => document.querySelector(".react-flow__viewport")?.style.transform ?? "";
  let guard = 0;
  while (guard++ < 12) {
    const scale = Number((transform().match(/scale\(([\d.]+)\)/) ?? [])[1] ?? 1);
    if (scale <= 0.36) break;
    zoomOut?.dispatchEvent(new MouseEvent("click", { bubbles: true }));
    out.clicks += 1;
  }
  out.transformAfter = transform();
  out.statusAfter = document.querySelector(".canvas-statusbar span")?.textContent;
  const header = document.querySelector(".canvas-region > header");
  if (header) {
    const rect = header.getBoundingClientRect();
    const effectiveScale = rect.width / header.offsetWidth;
    const computed = getComputedStyle(header.querySelector("strong"));
    const basePx = parseFloat(computed.fontSize);
    out.regionName = { basePx, effectivePx: Math.round(basePx * effectiveScale * 10) / 10, effectiveScale: Math.round(effectiveScale * 100) / 100 };
  }
  const label = document.querySelector(".object-node.emphasis-primary .object-label") ?? document.querySelector(".object-label");
  if (label) {
    const rect = label.getBoundingClientRect();
    const effectiveScale = rect.width / label.offsetWidth;
    const basePx = parseFloat(getComputedStyle(label).fontSize);
    out.objectLabel = { basePx, effectivePx: Math.round(basePx * effectiveScale * 10) / 10 };
  }
  return out;
}

